            // TODO API_TEST_START
            int expectedWidth = sourceImage.getWidth() + 50;
            int expectedHeight = sourceImage.getHeight() + 50;

            net.coobird.thumbnailator.filters.Canvas canvasFilter = new net.coobird.thumbnailator.filters.Canvas(
